  { n: 6279, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "What time did he ___ at the party? (arrive)", options: ["turn up", "turn down", "turn into", "turn off"], answer: "turn up", explanation: "Turn up: xuất hiện, đến." },
  { n: 6280, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "She ___ the job offer. (refused)", options: ["turned into", "turned down", "turned over", "turned up"], answer: "turned down", explanation: "Turn down: từ chối." },
  { n: 6281, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "Please ___ the lights when you leave.", options: ["turn down", "turn up", "turn off", "turn into"], answer: "turn off", explanation: "Turn off: tắt." },
  { n: 6282, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "The prince ___ a frog. (changed into)", options: ["turned down", "turned off", "turned into", "turned up"], answer: "turned into", explanation: "Turn into: biến thành." },
  { n: 6283, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "The meeting was ___ until next week. (postponed)", options: ["put on", "put up", "put out", "put off"], answer: "put off", explanation: "Put off: hoãn lại." },
  { n: 6284, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "It's cold. ___ your jacket.", options: ["Put up", "Put out", "Put off", "Put on"], answer: "Put on", explanation: "Put on: mặc vào." },
  { n: 6285, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "The firefighters ___ the fire. (extinguished)", options: ["put off", "put on", "put up", "put out"], answer: "put out", explanation: "Put out: dập tắt." },
  { n: 6286, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "I can't ___ his noise any longer. (tolerate)", options: ["put on", "put up with", "put out", "put off"], answer: "put up with", explanation: "Put up with: chịu đựng." },
  { n: 6287, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "Please ___ your toys. (return to their place)", options: ["put off", "put out", "put on", "put away"], answer: "put away", explanation: "Put away: cất đi." },
  { n: 6288, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "Can you ___ the volume? It's too loud. (reduce)", options: ["turn into", "turn down", "turn off", "turn up"], answer: "turn down", explanation: "Turn down: vặn nhỏ." },
  { n: 6289, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "Could you ___ the radio? I can't hear. (increase)", options: ["turn up", "turn down", "turn off", "turn into"], answer: "turn up", explanation: "Turn up: vặn to." },
  { n: 6290, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "They ___ a tent in the garden. (erected)", options: ["put away", "put out", "put off", "put up"], answer: "put up", explanation: "Put up: dựng lên." },
  { n: 6291, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "Which sentence is correct?", options: ["I look forward see you.", "I look forward to see you.", "I look forward seeing you.", "I look forward to seeing you."], answer: "I look forward to seeing you.", explanation: "Look forward to + V-ing." },
  { n: 6292, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "Which sentence is incorrect?", options: ["I put on the phone and fell asleep.", "He turned the radio off.", "She looks after her baby.", "They brought up three children."], answer: "I put on the phone and fell asleep.", explanation: "Phải là turned off the phone." },
  { n: 6293, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "He ___ his glasses to read the sign. (put on)", options: ["put out", "put on", "put away", "put off"], answer: "put on", explanation: "Put on: đeo vào." },
  { n: 6294, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "It ___ that he was lying. (became known)", options: ["turned up", "turned down", "turned on", "turned out"], answer: "turned out", explanation: "Turn out: hóa ra là." },
  { n: 6295, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "Children often ___ their parents. (admire)", options: ["look into", "look down on", "look out for", "look up to"], answer: "look up to", explanation: "Look up to: kính trọng, ngưỡng mộ." },
  { n: 6296, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "He ___ people who don't work hard. (despises)", options: ["looks down on", "looks out", "looks up to", "looks after"], answer: "looks down on", explanation: "Look down on: coi thường." },
  { n: 6297, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "___! The car is coming.", options: ["Look up", "Look into", "Look out", "Look for"], answer: "Look out", explanation: "Look out: coi chừng." },
  { n: 6298, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "The baby ___ his father. (resembles)", options: ["looks after", "looks into", "looks like", "looks up"], answer: "looks like", explanation: "Look like: trông giống." },
  { n: 6299, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "He ___ a good idea. (suggested)", options: ["brought in", "brought out", "brought up", "brought on"], answer: "brought up", explanation: "Bring up: đề cập vấn đề." },
  { n: 6300, level: "B1", topic: "Cụm động từ", grammarId: "099", question: "They ___ the lights to save energy. (switched off)", options: ["turned off", "turned down", "turned into", "turned up"], answer: "turned off", explanation: "Turn off: tắt." }
